function mdl = build_enr312_simulink(outDir)
%BUILD_ENR312_SIMULINK  Generate the Simulink model enr312_pendulum.slx.
%
%   build_enr312_simulink()            writes matlab/simulink/enr312_pendulum.slx
%
%   The model is generated by this script, so it can be rebuilt, reviewed and
%   versioned like code. It contains:
%     Firmware     discrete, every 2 ms: the firmware's control loop for any
%                  experiment (1-10, 21-24), from the sensor readings to the arm
%                  velocity the step generator runs (Enr312Firmware.m)
%     Arm          the arm angle is the integral of that velocity
%     Pendulum     the nonlinear rigid pendulum on the rotating arm,
%                  psi'' = -wg2 sin psi + wr2 cos psi theta'' + theta'^2 sin psi cos psi
%                          - gamma psi' - c tanh(psi'/w) + tap
%                  integrated as psi and w = psi' - wr2 cos psi theta', so that the
%                  arm's velocity steps act on the pendulum exactly as on the rig
%     Sensors      the microstep count (0.1125 deg) and the encoder (0.15 deg)
%   Parameters come from the workspace struct P (enr312_simulink_params). The
%   easiest way to run it is enr312_simulink(exp).
    here = fileparts(mfilename('fullpath'));
    if nargin < 1, outDir = here; end
    mdl = 'enr312_pendulum';
    if bdIsLoaded(mdl), close_system(mdl, 0); end
    new_system(mdl); load_system(mdl);
    set_param(mdl, 'Solver', 'ode45', 'MaxStep', '5e-4', 'RelTol', '1e-6', 'StopTime', 'P.stopTime', ...
        'SaveOutput', 'off', 'SaveTime', 'off', 'ReturnWorkspaceOutputs', 'on');
    add = @(src, name, pos, varargin) add_block(src, [mdl '/' name], 'Position', pos, varargin{:});
    ln = @(a, b) add_line(mdl, a, b, 'autorouting', 'smart');

    % ---- firmware (discrete, 500 Hz) -------------------------------------------------
    add('simulink/User-Defined Functions/MATLAB Function', 'Firmware', [380 60 540 260]);
    setCode([mdl '/Firmware'], firmwareCode(), 'P.Ts');
    % ---- arm: velocity (deg/s) -> angle ----------------------------------------------------
    add('simulink/Continuous/Integrator', 'arm angle', [640 70 680 110]);
    add('simulink/Discontinuities/Quantizer', 'microsteps', [740 70 780 110], 'QuantizationInterval', 'P.stepDeg');
    add('simulink/Math Operations/Gain', 'deg2rad arm rate', [640 150 690 180], 'Gain', 'pi/180');
    % ---- pendulum (continuous) ------------------------------------------------------------
    add('simulink/User-Defined Functions/MATLAB Function', 'Pendulum dynamics', [640 300 800 440]);
    setCode([mdl '/Pendulum dynamics'], plantCode(), '');
    add('simulink/Continuous/Integrator', 'pendulum angle', [870 310 910 350], 'InitialCondition', 'P.psi0*pi/180');
    add('simulink/Continuous/Integrator', 'w', [870 390 910 430]);
    add('simulink/Sources/Clock', 'clock', [470 400 490 420]);
    add('simulink/User-Defined Functions/MATLAB Function', 'Tap', [520 390 580 430]);
    setCode([mdl '/Tap'], tapCode(), '');
    % ---- sensors ------------------------------------------------------------------------------
    add('simulink/Math Operations/Gain', 'rad2deg pend', [970 315 1010 345], 'Gain', '180/pi');
    add('simulink/Math Operations/Bias', 'encoder zero', [1040 315 1080 345], 'Bias', 'P.bias');
    add('simulink/Discontinuities/Quantizer', 'encoder', [1110 315 1150 345], 'QuantizationInterval', 'P.encDeg');
    % ---- logging and scopes ------------------------------------------------------------------
    names = {'theta_deg', 'psi_deg', 'u', 'phase', 'ref', 'v'};
    pos = {[850 20 910 50], [1220 280 1280 310], [640 210 700 240], [640 250 700 280], [850 200 910 230], [760 140 820 170]};
    for i = 1:numel(names)
        add('simulink/Sinks/To Workspace', ['log ' names{i}], pos{i}, 'VariableName', names{i}, 'SaveFormat', 'Timeseries');
    end
    add('simulink/Sinks/Scope', 'Scope arm theta, pendulum psi', [1220 90 1260 150], 'NumInputPorts', '2');
    add('simulink/Sinks/Scope', 'Scope input u', [760 230 800 270]);

    % ---- wiring ----------------------------------------------------------------------------------
    ln('Firmware/1', 'arm angle/1');
    ln('arm angle/1', 'microsteps/1');
    ln('microsteps/1', 'Firmware/1');
    ln('Firmware/1', 'deg2rad arm rate/1');
    ln('deg2rad arm rate/1', 'Pendulum dynamics/3');
    ln('pendulum angle/1', 'Pendulum dynamics/1');
    ln('w/1', 'Pendulum dynamics/2');
    ln('clock/1', 'Tap/1');
    ln('Tap/1', 'Pendulum dynamics/4');
    ln('Firmware/5', 'Pendulum dynamics/5');
    ln('Pendulum dynamics/1', 'pendulum angle/1');
    ln('Pendulum dynamics/2', 'w/1');
    ln('pendulum angle/1', 'rad2deg pend/1');
    ln('rad2deg pend/1', 'encoder zero/1');
    ln('encoder zero/1', 'encoder/1');
    ln('encoder/1', 'Firmware/2');
    ln('microsteps/1', 'log theta_deg/1');
    ln('encoder/1', 'log psi_deg/1');
    ln('Firmware/2', 'log u/1');
    ln('Firmware/3', 'log phase/1');
    ln('Firmware/4', 'log ref/1');
    ln('Firmware/1', 'log v/1');
    ln('microsteps/1', 'Scope arm theta, pendulum psi/1');
    ln('encoder/1', 'Scope arm theta, pendulum psi/2');
    ln('Firmware/2', 'Scope input u/1');
    add_block('built-in/Note', [mdl '/note'], 'Position', [380 520], 'Text', ...
        ['ENR312 / STEVAL-EDUKIT01 rotary inverted pendulum. Generated by build_enr312_simulink.m. ' ...
         'Easiest: enr312_simulink(exp). Or P = enr312_simulink_params(exp), then Run.']);
    file = fullfile(outDir, [mdl '.slx']);
    save_system(mdl, file); close_system(mdl, 0);
    fprintf('wrote %s\n', file);
end

function setCode(blk, code, sampleTime)
% put the code into a MATLAB Function block and declare P a parameter
    rt = sfroot; ch = rt.find('-isa', 'Stateflow.EMChart', 'Path', blk);
    ch.Script = code;
    d = ch.find('-isa', 'Stateflow.Data', 'Name', 'P');
    if ~isempty(d), d.Scope = 'Parameter'; d.Tunable = false; end
    if ~isempty(sampleTime), ch.ChartUpdate = 'DISCRETE'; ch.SampleTime = sampleTime; end
end

function s = firmwareCode()
s = strjoin({
'function [v, u, phase, ref, held] = Firmware(rotor, psi, P)'
'% The firmware''s control loop, one call per 2 ms tick (Enr312Firmware.m, a port of'
'% firmware/enr312/src). rotor: the arm in microsteps (deg); psi: the encoder (deg).'
'% v: arm velocity for the next tick (deg/s); u: plant input (deg/s^2); held: 1 while'
'% the operator''s hand holds the pendulum at the start of an upright experiment.'
'coder.extrinsic(''enr312_fw_tick'');'
'persistent first'
'if isempty(first), first = true; end'
'v = 0; u = 0; phase = 0; ref = 0; held = 0;'
'[v, u, phase, ref, held] = enr312_fw_tick(first, rotor, psi, P);'
'first = false;'
'end'}, newline);
end

function s = plantCode()
s = strjoin({
'function [psidot, wdot] = Pendulum_dynamics(psi, w, thetadot, tap, held, P)'
'% rigid pendulum on a rotating arm (docs/first_principles/ROTARY_PENDULUM_DYNAMICS.md, eq. 6)'
'% plus dry pivot friction, smoothed as c*tanh(psidot/width); all in rad.'
'% State w = psidot - wr2 cos(psi) thetadot removes the arm acceleration from the'
'% equation: a step in the arm velocity changes psidot by wr2 cos(psi) times the step.'
'if held > 0.5'
'    psidot = 0; wdot = 0; return;      % the hand holds it still'
'end'
'psidot = w + P.wr2 * cos(psi) * thetadot;'
'wdot = -P.wg2 * sin(psi) + thetadot^2 * sin(psi) * cos(psi) - P.gamma * psidot ...'
'       - P.coulomb * tanh(psidot / P.coulombWidth) + P.wr2 * sin(psi) * psidot * thetadot + tap;'
'end'}, newline);
end

function s = tapCode()
s = strjoin({
'function a = Tap(t, P)'
'% a tap: P.tapRate deg/s added to the rate of the tilt from upright, spread over'
'% P.tapWidth s. The tilt from upright is 180 deg - psi.'
'a = 0;'
'if P.tapRate ~= 0 && t >= P.tapTime && t < P.tapTime + P.tapWidth'
'    a = -P.tapRate * pi / 180 / P.tapWidth;'
'end'
'end'}, newline);
end
